#include "bloodborne_ssinfo_reference.h"

#include <QCryptographicHash>

namespace Bloodborne {
namespace {

constexpr char ReferencePayload[] =
    R"ssinfo()ssinfo";

static_assert(sizeof(ReferencePayload) - 1 == ReferenceServerStatusInfoSize);

bool FailValidation(QString* error, const QString& message) {
    if (error != nullptr)
        *error = message;
    return false;
}

} // namespace

const QByteArray& ReferenceServerStatusInfo() {
    static const QByteArray payload(ReferencePayload, ReferenceServerStatusInfoSize);
    return payload;
}

bool ValidateReferenceServerStatusInfo(QString* error, QByteArray* decodedXml) {
    const QByteArray& body = ReferenceServerStatusInfo();
    if (body.size() != ReferenceServerStatusInfoSize) {
        return FailValidation(error, QStringLiteral("encoded size is %1; expected %2")
                                         .arg(body.size())
                                         .arg(ReferenceServerStatusInfoSize));
    }
    if (!body.startsWith("PHNzPjA8L3")) {
        return FailValidation(error,
                              QStringLiteral("encoded payload does not start with PHNzPjA8L3"));
    }

    const QByteArray bodyHash =
        QCryptographicHash::hash(body, QCryptographicHash::Sha256).toHex().toUpper();
    if (bodyHash != ReferenceServerStatusInfoSha256) {
        return FailValidation(error,
                              QStringLiteral("encoded SHA-256 is %1; expected %2")
                                  .arg(QString::fromLatin1(bodyHash),
                                       QString::fromLatin1(ReferenceServerStatusInfoSha256)));
    }

    const auto decodedResult =
        QByteArray::fromBase64Encoding(body, QByteArray::AbortOnBase64DecodingErrors);
    if (!decodedResult)
        return FailValidation(error, QStringLiteral("payload is not strict Base64"));

    const QByteArray decoded = decodedResult.decoded;
    if (decoded.size() != ReferenceDecodedServerStatusInfoSize) {
        return FailValidation(error, QStringLiteral("decoded size is %1; expected %2")
                                         .arg(decoded.size())
                                         .arg(ReferenceDecodedServerStatusInfoSize));
    }
    if (!decoded.startsWith("<ss>0</ss>"))
        return FailValidation(error, QStringLiteral("decoded XML does not start with <ss>0</ss>"));
    if (!decoded.contains("<gameurl2>"))
        return FailValidation(error, QStringLiteral("decoded XML does not contain <gameurl2>"));

    const qsizetype apiCount = decoded.count("<api_");
    if (apiCount != 37) {
        return FailValidation(
            error, QStringLiteral("decoded XML contains %1 api_* tags; expected 37").arg(apiCount));
    }

    const QByteArray decodedHash =
        QCryptographicHash::hash(decoded, QCryptographicHash::Sha256).toHex().toUpper();
    if (decodedHash != ReferenceDecodedServerStatusInfoSha256) {
        return FailValidation(
            error, QStringLiteral("decoded SHA-256 is %1; expected %2")
                       .arg(QString::fromLatin1(decodedHash),
                            QString::fromLatin1(ReferenceDecodedServerStatusInfoSha256)));
    }

    if (decodedXml != nullptr)
        *decodedXml = decoded;
    if (error != nullptr)
        error->clear();
    return true;
}

} // namespace Bloodborne
